import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Fundamentos de combate","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/overview.md","filePath":"es/game-design/combat/overview.md"}'),s={name:"es/game-design/combat/overview.md"};function t(r,a,d,c,l,m){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="combat-foundations" tabindex="-1">Fundamentos de combate <a class="header-anchor" href="#combat-foundations" aria-label="Enlace permanente a &quot;Fundamentos de combate&quot;">​</a></h1><p><a href="/Syrolands-Public/es/guide/combat/overview.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/">Índice de especificaciones</a></p><p><strong>Estado del diseño: Aceptado para los fundamentos y las políticas experimentales de Slice 0; Propuesto para las mecánicas avanzadas. Implementación: combate cuerpo a cuerpo localizado natural y Anatomy cualitativa de Stage 2A. Verificación: pruebas automatizadas y primera observación del cliente registradas; validación ampliada de juego/equilibrio incompleta. Aquí no se verifica la disponibilidad actual.</strong></p><p><strong>Baseline experimental anterior con estado Aceptado:</strong> los ataques ordinarios de War Mode/Combatant siguen siendo automáticos. La interacción avanzada es una entrada opcional a oportunidades resueltas por el servidor; no debe exigir hacer clic en cada golpe. Los participantes elegibles pueden someterse a simulación local aunque nunca abran un panel de evaluación.</p><p>Separar la solicitud de golpear una región del acierto/fallo y de la ubicación real del impacto. Las decisiones del jugador y las habilidades del personaje coexisten. Las oportunidades visibles para el cliente no transfieren autoridad al renderizado, los píxeles de sprites ni la finalización de animaciones.</p><p>El Lab inicial usa UOR/pre-AOS. PvP y PvM comparten el sistema conceptual previsto; la primera configuración limitada a jugadores humanos es una frontera de implementación temporal.</p><p>ModernUO actual dispone de tiempos, comprobaciones de impacto, Hits globales, mitigación de escudo/armadura y sorteos de cobertura heredados. Stage 2A integra las primitivas de siete regiones, estado de jugadores limitado a la sesión y trauma local natural sin sustituir el daño de HP global. <strong>Carencia:</strong> intención de apuntado, incapacitación funcional/comportamiento del escudo y validación de juego siguen aplazados.</p><p>Consultar <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">regiones</a>, <a href="/Syrolands-Public/es/game-design/combat/damage.html">daño</a>, <a href="/Syrolands-Public/es/game-design/combat/targeting.html">apuntado</a> e <a href="/Syrolands-Public/es/game-design/combat/disability.html">incapacitación</a>. Las <a href="/Syrolands-Public/es/game-design/combat/future-directions.html">mecánicas futuras</a> quedan fuera de Slice 0.</p><h2 id="proposed-progression-and-stat-responsiveness" tabindex="-1">Progresión y respuesta de stats con estado Propuesto <a class="header-anchor" href="#proposed-progression-and-stat-responsiveness" aria-label="Enlace permanente a &quot;Progresión y respuesta de stats con estado Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/stats.html">Stats y respuesta del combate</a> exige una cadencia creíble con DEX baja, manteniendo separadas la animación, recuperación, oportunidades de ataque, stamina/fatiga y velocidad del arma. Es intención con estado Propuesto; los tiempos heredados del servidor dependen actualmente de stamina y velocidad del arma en la ruta pre-AOS. Aquí no se cambia ningún ataque, fórmula de tiempos ni animación del cliente. La <a href="/Syrolands-Public/es/game-design/characters/progression.html">progresión general</a> pide juego útil con habilidad baja y una futura revisión de la inversión obligatoria en habilidades, preservando el combate automático y la autoridad del servidor.</p><h2 id="combat-foundation-integration" tabindex="-1">Integración de fundamentos de combate <a class="header-anchor" href="#combat-foundation-integration" aria-label="Enlace permanente a &quot;Integración de fundamentos de combate&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Armas y familias de daño</a>, <a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">armadura y mitigación</a> y <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">stamina, recuperación y entrada reactiva</a> amplían direcciones con estado Propuesto alrededor del experimento aceptado existente. <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado del combate y preguntas abiertas</a> separa diseño, implementación, habilitación fechada y verificación. Los ataques manuales obligatorios entrarían en conflicto con la baseline automática aceptada; no se selecciona ningún reemplazo.</p><p>La habilidad del personaje determina la capacidad, el conocimiento informa las opciones y la ejecución del jugador determina el rendimiento dentro de reglas resueltas por el servidor. La diversidad de builds debería evitar que todo combatiente deba maximizar habilidad de arma, Tactics, Anatomy y Healing. Un Hunter ilustrativo puede mezclar Archery, Tracking, Animal Lore, Anatomy, Tailoring, Tactics y Healing/Camping a distintos niveles; un guerrero pesado puede centrarse en armadura y control cuerpo a cuerpo; un mago puede priorizar conocimiento de hechizos, Concentration y posicionamiento. Son ejemplos con estado Propuesto, no plantillas cerradas ni builds óptimas aprobadas.</p><h2 id="batch-05-—-proposed-dual-mode-direction" tabindex="-1">Batch 05 — dirección propuesta de dos modos <a class="header-anchor" href="#batch-05-—-proposed-dual-mode-direction" aria-label="Enlace permanente a &quot;Batch 05 — dirección propuesta de dos modos&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Combate Legacy y Modern</a> define ahora la terminología y las reglas propuestas de inicio/cola. Modern es la dirección experimental preferida, todavía con estado Propuesto; Legacy sigue siendo la alternativa de diseño compatible. Esto aclara la ambigüedad anterior sobre un reemplazo manual obligatorio sin sustituir el experimento con estado Aceptado ni afirmar que el sistema de modos esté terminado.</p><p><a href="/Syrolands-Public/es/game-design/combat/actions.html">Combat Actions / Special Attacks</a> · <a href="/Syrolands-Public/es/game-design/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/game-design/combat/reach-and-spacing.html">Alcance y distancia</a> · <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity compartida</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a>.</p>',16)])])}const g=e(s,[["render",t]]);export{u as __pageData,g as default};
